/// Validates that the fee split matches Zion protocol specification.
/// Expected: miner 89%, humanitarian 5%, Issobella 5%, pool 1%
pub fn validate_zion_fee_split(
    block_reward: u64,
    miner: u64,
    humanitarian: u64,
    issobella: u64,
    pool: u64,
