        Commands::Miners => {
            println!("Connected miners would be listed here");
        }
        Commands::Split { reward } => {
            let split = FeeSplit {
                miner_pct: reward * 0.89,
                humanitarian_pct: reward * 0.05,
                issobella_pct: reward * 0.05,
