use clap::{Parser, Subcommand};
use reqwest;
use serde::Deserialize;

#[derive(Parser)]
#[command(name = "zion-pool-cli")]
#[command(about = "Zion mining pool command line tool")]
struct Cli {
    #[arg(short, long, default_value = "http://localhost:8444")]
    pool_url: String,

    #[command(subcommand)]
    command: Commands,
}

