            targetChain: targetChain,
            targetAddress: targetAddress,
            timestamp: block.timestamp,
            processed: false
        });

        totalLocked += netAmount;
        emit DepositLocked(depositId, msg.sender, netAmount, targetChain);
    }

    function release(
        bytes32 depositId,
        bytes32 nonce,
        address recipient,
