        if self.requested_amount > MAX_REQUEST {
            return Err(ProposalError::AmountTooHigh);
        }
        if self.voting_ends_at - self.created_at < Duration::days(14) {
            return Err(ProposalError::VotingPeriodTooShort);
        }
        Ok(())
    }
