            };
            println!("Fee Split for reward {}:", reward);
            println!("  Miner: {:.4}", split.miner_pct);
            println!("  Humanitarian: {:.4}", split.humanitarian_pct);
            println!("  Issobella: {:.4}", split.issobella_pct);
            println!("  Pool: {:.4}", split.pool_pct);
        }
    }

    Ok(())
}
