    #[test]
    fn test_valid_split() {
        assert!(validate_zion_fee_split(100, 89, 5, 5, 1));
    }

    #[test]
    fn test_invalid_split() {
        assert!(!validate_zion_fee_split(100, 90, 5, 5, 1));
    }
}
