    Split { reward: f64 },
}

#[derive(Deserialize, Debug)]
struct PoolStats {
    total_hashrate: f64,
    active_miners: usize,
    blocks_found: u64,
    fee_split: FeeSplit,
}

#[derive(Deserialize, Debug)]
struct FeeSplit {
    miner_pct: f64,
    humanitarian_pct: f64,
    issobella_pct: f64,
    pool_pct: f64,
}

#[tokio::main]
